package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.repositories.*;
import com.pet.buscaativa.services.*;
import org.springframework.mock.web.MockHttpServletResponse;

class SpecificFrequencyCorrectionTests extends AgendaIntegritySupport {
    static final String REASON="Comparecimento confirmado após conferência do prontuário sintético.";
    @MockitoSpyBean HistoricoPacienteService histories;
    @MockitoSpyBean AuditoriaCorrecaoService auditService;
    @Autowired PacienteService clinical;
    @Autowired AuditoriaCorrecaoRepository audits;
    @Autowired Clock clock;
    @Autowired UsfReferenciaRepository usfs;
    Agendamento fact(SituacaoAtendimento before){return tx(()->{var a=seed(patient,professional,before,LocalDate.now().minusDays(5),"08:00");histories.registrarAlteracaoDeAtendimento(a,SituacaoAtendimento.AGENDADO);clinical.recalcularAssiduidadePaciente(patients.findById(patient.getId()).orElseThrow());return a;});}
    Object database(){var ds=Objects.requireNonNull(jdbc.getDataSource());return LegacyMigrationFixture.snapshot(ds,LegacyMigrationFixture.columns(ds));}
    Usuario actor(String role){return switch(role){case "owner"->professional;case "admin"->admin;case "colleague"->colleague;case "reception"->tx(()->user(TipoUsuario.RECEPCAO,UnidadeAtuacao.CAPS_AD));case "foreign"->tx(()->user(TipoUsuario.ADMINISTRADOR,UnidadeAtuacao.CAPS_I));default->throw new IllegalArgumentException();};}
    MockHttpServletResponse request(Usuario actor,Agendamento a,Object dto) throws Exception{return mvc.perform(patch("/api/agendamentos/"+a.getId()+"/frequencia/correcao").header("Authorization","Bearer "+tokens.gerarToken(actor)).contentType("application/json").content(json.writeValueAsString(dto))).andReturn().getResponse();}
    CorrigirFrequenciaDTO dto(Agendamento a,FrequenciaAssistencial next){return new CorrigirFrequenciaDTO(next,a.getVersion(),REASON);}
    @ParameterizedTest @CsvSource({"FALTOU,owner,200","PRESENTE,owner,200","FALTOU,admin,200","PRESENTE,admin,200","FALTOU,colleague,403","PRESENTE,colleague,403","FALTOU,reception,403","PRESENTE,reception,403","FALTOU,foreign,404","PRESENTE,foreign,404"})
    void cf01And02And09To11RoleAndOwnershipAreEnforced(SituacaoAtendimento before,String role,int expected) throws Exception {
        var a=fact(before);var actor=actor(role);var previous=database();long events=history.count(),rows=appointments.count(),count=audits.count();var next=before==SituacaoAtendimento.FALTOU?FrequenciaAssistencial.PRESENTE:FrequenciaAssistencial.FALTOU;
        var r=request(actor,a,dto(a,next));assertEquals(expected,businessStatus(r),r.getContentAsString());if(expected!=200){assertEquals(previous,database());return;}
        var response=json.readTree(r.getContentAsString());assertEquals(next.name(),response.get("frequenciaAssistencial").asText());assertEquals(a.getVersion()+1,response.get("version").asInt());assertEquals(rows,appointments.count());assertEquals(events,history.count());assertEquals(count+1,audits.count());
        var audit=jdbc.queryForMap("select * from tb_auditoria_correcao_frequencia where agendamento_id=?",a.getId());assertEquals(actor.getId(),audit.get("ATOR_ID"));assertEquals(professional.getId(),audit.get("RESPONSAVEL_ID"));assertEquals(before.name(),audit.get("FREQUENCIA_ANTERIOR"));assertEquals(next.name(),audit.get("FREQUENCIA_NOVA"));assertEquals(REASON,audit.get("JUSTIFICATIVA"));assertEquals(0,audit.get("VERSAO_ANTERIOR"));assertEquals(1,audit.get("VERSAO_RESULTANTE"));assertEquals(professional.getId(),jdbc.queryForObject("select profissional_id from tb_historico_paciente where agendamento_id=? and tipo in ('FALTA','PRESENCA')",Long.class,a.getId()));
    }
    @ParameterizedTest @EnumSource(value=SituacaoAtendimento.class,names={"PRESENTE","FALTOU"})
    void cf03And04SameFrequencyWithCurrentVersionIsIdempotentButStaleVersionIsConflict(SituacaoAtendimento state) throws Exception {var a=fact(state);var before=database();assertEquals(200,request(professional,a,dto(a,FrequenciaAssistencial.valueOf(state.name()))).getStatus());assertEquals(before,database());var next=state==SituacaoAtendimento.PRESENTE?FrequenciaAssistencial.FALTOU:FrequenciaAssistencial.PRESENTE;assertEquals(200,request(professional,a,dto(a,next)).getStatus());before=database();assertEquals(409,request(professional,a,dto(a,next)).getStatus());assertEquals(before,database());a=appointment(a.getId());assertEquals(200,request(professional,a,dto(a,next)).getStatus());assertEquals(before,database());}
    @ParameterizedTest @EnumSource(value=SituacaoAtendimento.class,names={"AGENDADO","REMARCADO","CANCELADO","REMARCADO_ORIGEM"})
    void cf05And06UnknownInitialOrCanceledFactIsNeverRegularizedByCorrectionRoute(SituacaoAtendimento state) throws Exception {var a=fact(state);var before=database();assertTrue(Set.of(409,422).contains(request(admin,a,dto(a,FrequenciaAssistencial.PRESENTE)).getStatus()));assertEquals(before,database());}
    @Test void cf06CancellationWithKnownFrequencyStillRequiresStageFive() throws Exception {var a=fact(SituacaoAtendimento.PRESENTE);tx(()->{var x=appointment(a.getId());x.setSituacaoAtendimento(SituacaoAtendimento.CANCELADO);appointments.saveAndFlush(x);return null;});var before=database();var r=request(admin,appointment(a.getId()),dto(appointment(a.getId()),FrequenciaAssistencial.FALTOU));assertEquals(422,r.getStatus());assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"AGENDADO","REMARCADO","CANCELADO","REMARCADO_ORIGEM","NAO_REGISTRADA"})
    void invalidFrequencyDestinationCannotBecomeABookingCommand(String target) throws Exception {var a=fact(SituacaoAtendimento.FALTOU);var before=database();var r=request(admin,a,Map.of("novaFrequencia",target,"version",a.getVersion(),"justificativa",REASON));assertEquals(target.equals("NAO_REGISTRADA")?422:400,r.getStatus());assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"missing_frequency","missing_version","negative_version","missing_reason","blank_reason","short_reason","generic_reason","long_reason"})
    void cf12And13InvalidBodyHasNoPartialWrite(String defect) throws Exception {var a=fact(SituacaoAtendimento.FALTOU);var payload=new HashMap<String,Object>();payload.put("novaFrequencia","PRESENTE");payload.put("version",a.getVersion());payload.put("justificativa",REASON);switch(defect){case "missing_frequency"->payload.remove("novaFrequencia");case "missing_version"->payload.remove("version");case "negative_version"->payload.put("version",-1);case "missing_reason"->payload.remove("justificativa");case "blank_reason"->payload.put("justificativa","   ");case "short_reason"->payload.put("justificativa","curto");case "generic_reason"->payload.put("justificativa","não informado");case "long_reason"->payload.put("justificativa","a".repeat(2001));default->throw new IllegalArgumentException();}var before=database();assertEquals(422,request(admin,a,payload).getStatus());assertEquals(before,database());}
    @Test void newContractDoesNotTrustClientActorTimeOrBookingFields() throws Exception {var a=fact(SituacaoAtendimento.FALTOU);var body=new HashMap<String,Object>();body.put("novaFrequencia","PRESENTE");body.put("version",a.getVersion());body.put("justificativa",REASON);body.put("usuarioId",colleague.getIdPublico());body.put("responsavelAtendimentoId",colleague.getIdPublico());body.put("ocorridoEm","1999-01-01T00:00:00Z");body.put("situacaoReserva","CANCELADA");assertEquals(200,request(admin,a,body).getStatus());var row=audits.findByAgendamento_IdAndUnidade(a.getId(),"CAPS:CAPS_AD",org.springframework.data.domain.Pageable.unpaged()).getContent().get(0);assertEquals(admin.getId(),row.getAtor().getId());assertEquals(professional.getId(),row.getResponsavel().getId());assertEquals(clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),row.getOcorridoEm());assertEquals(SituacaoReserva.AGENDADA,appointment(a.getId()).getSituacaoReserva());}
    @Test void sameGenericFrequencyFromUnauthorizedColleagueDoesNotMaskAccessDenial() throws Exception {var a=fact(SituacaoAtendimento.FALTOU);var before=database();assertEquals(403,request(colleague,a,dto(a,FrequenciaAssistencial.FALTOU)).getStatus());assertEquals(before,database());}
    @Test void unauthenticatedCorrectionIs401() throws Exception {var a=fact(SituacaoAtendimento.FALTOU);var before=database();assertEquals(401,mvc.perform(patch("/api/agendamentos/"+a.getId()+"/frequencia/correcao").contentType("application/json").content(json.writeValueAsString(dto(a,FrequenciaAssistencial.PRESENTE)))).andReturn().getResponse().getStatus());assertEquals(before,database());}
    @Test void differentUsfIsNotAuthorizedByGenericUnitType() throws Exception {var pair=tx(()->{var x=new UsfReferencia();x.setCnes(UUID.randomUUID().toString());usfs.saveAndFlush(x);var y=new UsfReferencia();y.setCnes(UUID.randomUUID().toString());usfs.saveAndFlush(y);var owner=user(TipoUsuario.PROFISSIONAL,UnidadeAtuacao.USF);owner.setUsfAtuacao(x);users.saveAndFlush(owner);var external=user(TipoUsuario.ADMINISTRADOR,UnidadeAtuacao.USF);external.setUsfAtuacao(y);users.saveAndFlush(external);var p=patients.findById(patient.getId()).orElseThrow();p.setCapsReferencia(null);p.setUsfReferencia(x);patients.saveAndFlush(p);return new Object[]{seed(p,owner,SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(5),"08:00"),external};});var a=(Agendamento)pair[0];var before=database();assertEquals(404,request((Usuario)pair[1],a,dto(a,FrequenciaAssistencial.PRESENTE)).getStatus());assertEquals(before,database());}
    @Test void cf16DirectServiceValidatesVersionDestinationAndReason(){var a=fact(SituacaoAtendimento.FALTOU);var before=database();authenticate();assertThrows(com.pet.buscaativa.services.exceptions.ValidationException.class,()->service.corrigirFrequencia(a.getId(),new CorrigirFrequenciaDTO(FrequenciaAssistencial.PRESENTE,null,REASON)));assertThrows(com.pet.buscaativa.services.exceptions.ValidationException.class,()->service.corrigirFrequencia(a.getId(),new CorrigirFrequenciaDTO(FrequenciaAssistencial.NAO_REGISTRADA,a.getVersion(),REASON)));assertThrows(com.pet.buscaativa.services.exceptions.ValidationException.class,()->service.corrigirFrequencia(a.getId(),new CorrigirFrequenciaDTO(FrequenciaAssistencial.PRESENTE,a.getVersion(),null)));assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"history","audit_after_insert","frequency_flush"})
    void au05To07ActualWritesRollBackEveryTable(String failure){var a=fact(SituacaoAtendimento.FALTOU);var before=database();if(failure.equals("history"))doAnswer(i->{i.callRealMethod();throw new IllegalStateException("synthetic history failure");}).when(histories).registrarAlteracaoDeAtendimento(any(),any());else if(failure.equals("audit_after_insert"))doAnswer(i->{i.callRealMethod();throw new IllegalStateException("synthetic audit failure after insert");}).when(org.springframework.test.util.AopTestUtils.<AuditoriaCorrecaoService>getUltimateTargetObject(auditService)).registrarIndividual(any(),any(),anyString(),anyInt());else doAnswer(i->{appointments.flush();assertEquals("PRESENTE",jdbc.queryForObject("select frequencia_assistencial from tb_agendamento where id=?",String.class,a.getId()));throw new IllegalStateException("synthetic after frequency flush");}).when(histories).registrarAlteracaoDeAtendimento(any(),any());authenticate();assertThrows(IllegalStateException.class,()->service.corrigirFrequencia(a.getId(),dto(a,FrequenciaAssistencial.PRESENTE)));assertEquals(before,database());}
    @Test void individualBookingWithGroupFollowupReusesItsClinicalEventAcrossRepeatedCorrections() throws Exception {
        tx(()->{patient.setTipoAcompanhamento(TipoAcompanhamento.GRUPO_TERAPEUTICO);patients.saveAndFlush(patient);return null;});
        var a=fact(SituacaoAtendimento.FALTOU);long rows=appointments.count(),events=history.count(),count=audits.count();var eventIds=jdbc.queryForList("select id from tb_historico_paciente where agendamento_id=? and tipo in ('FALTA','PRESENCA','PARTICIPACAO_GRUPO_TERAPEUTICO') order by id",Long.class,a.getId());
        for(var next:List.of(FrequenciaAssistencial.PRESENTE,FrequenciaAssistencial.FALTOU,FrequenciaAssistencial.PRESENTE)){assertEquals(200,request(professional,a,dto(a,next)).getStatus());a=appointment(a.getId());assertEquals(events,history.count());assertEquals(eventIds,jdbc.queryForList("select id from tb_historico_paciente where agendamento_id=? and tipo in ('FALTA','PRESENCA','PARTICIPACAO_GRUPO_TERAPEUTICO') order by id",Long.class,a.getId()));}
        assertEquals(rows,appointments.count());assertEquals(count+3,audits.count());assertEquals(0,patients.findById(patient.getId()).orElseThrow().getCountFaltas());
    }
}
